        "kind": "mcq",
        "passageZh": "尽管方便快捷的“网络阅读”已经成为了一种生活时尚，但纸质阅读仍然发挥着很大的作用。日前，我们通过问卷调查、现场采访的方式对不同阶层的读者进行了调查，结果显示，市民电子阅读的兴趣日渐提高，但很多人仍在坚守传统的纸质阅读。在为期三天的阅读习惯调查中，记者发现，经常上网浏览书籍的读者占被调查者的60%，而从不选择上网浏览的读者仅占\n25%；在喜欢的阅读方式调查中，喜爱纸质阅读的读者高达90%，占绝对优势，而喜欢网上阅读的人只占到8%，很明显，读者还是更喜爱传统的阅读方式。许多读者表示传统图书提供了非常明了、有用的信息，阅读时没有广告等干扰，有效地防止了一些时间的浪费。另外，多数读者认为长期对着屏幕阅读，也容易带来很多后遗症：眼干、肩膀疼、腰疼等。纸质阅读更有利于保护眼睛。采访中，很多读者认为纸质书带给我们的不仅仅是书中的文字，更是手捧文化的一种美妙感觉，这是任何形式的电子阅读器都无法做到的。",
