        "kind": "mcq",
        "passageZh": "有三个孩子在树林里玩儿，都不小心让树枝挂破了裤子。面对裤腿上的破洞和孩子不安的脸，三位母亲用不同的态度处理了这件事情。第一位母亲大声教训了孩子之后，用一根线绳像系麻袋一样把那个破洞扎紧，整条裤腿因此显得皱皱巴巴。破洞是没有了，取而代之的那个结却像孩子撅起的小嘴。孩子也因此受到严厉的警告：“今后再也不准到树林里玩儿。”第二位母亲不打也不骂，默默地把那个破洞一针一线缝补好，裤子上留下了针线的痕迹。第三位母亲面对孩子裤腿上的破洞，安慰孩子：“不要紧，哪个小孩子不贪玩儿，你奶奶说你爸爸小时候比你还调皮呢。”她把孩子的裤子脱下来，用彩线在破洞上绣了朵漂亮的小红花，好像原本那里就有一朵花。孩子笑得好开心。同样的问题，因为用了三种不同的解决办法，就导致了不同的结果：第一位母亲让孩子感到恐惧和失望，那皱巴巴的裤腿就如同母亲脸上写满的愤怒，孩子不得不活在母亲强制的意愿中；第二位母亲平平常常，孩子得到的是一个顺其自然的生活环境；第三位母亲是最优秀的教育家，她用裤子上的花朵启发了孩子美好的想象，她脸上灿若朝阳的微笑给了孩子更多的宽容，让孩子在成长的路上充满自信并富有创造力。在我们现实生活中，第一种母亲不少，第二种母亲不多，我们缺少的是第三种母亲。",
