        "passageZh": "我们每个人都希望自己生活得快乐。快乐不是别人给的，而是来自于自己的心态，是自己内心的感受。同一件事，不同的人有不同的心态，因而便产生不同的结果。有三句看似很简单的话，曾经帮助很多人找到并体验了人生的快乐。这里，把这“三句话”送给你，只要经常使用它，你便能成为一个快乐的人。这三句话就是“太好了！”“我能行！”“我帮你！”乐观的人常说：“太好了！”这句看似不起眼的话反映的是一个人遇到困难还能面带微笑的心理素质。一起做同样作业的两个学生，开始时进度、质量都差不多，做了近一半儿的时候，一个说：“呀，太好了！作业已完成一半儿了。”另一个同学则说：“太糟了，做了这么久，才做了一半儿。”结果一个带着愉快心情完成作业，不但速度快，而且还轻松地记住了作业中需要巩固的内容。另一个则在烦躁心情的影响下，计算出错，越慢越急，越急越慢，最终作业的质量大受影响。自信的人爱说：“我能行！”“我能行”和“我不行”虽然只有一字之差，但却有着本质的不同。“我能行”是成功者必备的素质，而“我不行”则正是失败者的主要原因——失去了自信。快乐的人常说：“我帮你。”烦恼的人爱说：“你帮我。”助人为乐，不只是个词语，更是一种生活态度和为人的原则。如果你能真心、无私地帮助别人，你就能体验到人生的快乐，在帮助他人的过程中你会发现自己的价值，会有一种成就感。",
