        "kind": "mcq",
        "passageZh": "古时候，有一个农民要到另外一个村子去办事。由于当时交通不便，他只能走路去。不久他发现，要到达那个村子必须经过一条河，不然就得爬过一座高山。怎么办呢？是过河还是爬山？他正犹豫的时候，突然看到附近有一棵大树，于是他用斧头把大树砍倒，将树干砍凿成一条简易的小船。这个农民很佩服自己的聪明，他坐着自造的小船很轻松地就到达了对岸。上岸后，他觉得这条船实在很管用，如果丢弃在岸边太可惜了。而且万一前面再遇到河的话，他还得再砍树，辛苦地做成船。所以，他决定把船背在身上，以备不时之需。走啊走，背着船的农民累得满头大汗，因为船实在是太重了。他一直汗流浃背地走，却发现一路上都很平坦，在抵达那个村庄前没有再遇到河流，可他却多花了三倍的时间才到达目的地。人生不就是一次旅程吗？我们无法预测自己人生的道路会是什么样的，各种困难总是会突然出现，令我们始料不及，束手无策。但没有什么“船”能够始终让我们走得自在，轻松，它对我们而言，只能满足一时之需。",
