        "passageZh": "近年来的一些调查发现，那些“女主外、男主内”的家庭形式虽然大多是由于经济状况的无奈选择，却不一定不幸福。从某种角度来说，这种形式能更好地维护婚姻稳定。但过去很多人认为这给家庭稳定带来不好的影响：女性经济越来越独立甚至代替男人成为养家者，就容易给丈夫造成压力，婚姻更容易出现问题。但事实也许并非如此。调查显示，家庭经济中男女地位交换实际上对婚姻起了稳定作用，使离婚率更低，婚姻更幸福。一位社会学教授研究发现，在很多家庭中，夫妻双方同时工作并分担家务，比主要由丈夫养家的婚姻更稳定，离婚率更低。她以自己为例子，说：“在我的婚姻中，我比丈夫的学历高，现在他退休了，我的收入相对更高。当初我选择他因为他尊重我，也乐意和我分担日常生活中的各种责任。现在越来越多的女人有能力做相似的选择。”",
