        "partLabel": "Phần 3 • Đọc hiểu bài văn dài chọn đáp án (71–90)",
        "kind": "mcq",
        "passageZh": "父亲有位朋友，是位知名画家。几乎每次去他家，总能遇上有青年画家登门求教，他也总是很耐心地给人指点，还热心地向媒体推荐有潜力的青年画家，消耗了大量的时间和精力。我知道他的时间很宝贵，而提携后辈完全是尽义务，就忍不住问他：“伯父，您多画点儿画儿多好，何必把时间浪费在这些人的身上？”他笑着说：“我给你讲个故事吧。40 年前，有一个青年拿了自己的画，想请一位著名的画家指点一下。那画家看这青年是个无名小卒，连画都没让青年打开，就说自己有事，下了逐客令。那青年走到门口，转过身说：‘老师，您现在站在山顶，往下看我这个无名小卒，把我看得很渺小；但您也应该知道，我在山下往上看您，您也同样很渺小！’说完扬长而去。因为这件事，这青年后来努力学艺，总算有了一点儿小名气。但他时刻记得那一次冷遇，时刻提醒自己，一个人是否形象高大，并不在于他所处的位置，而在于他的人格、胸襟、修养——你猜对了，当年的那个年轻人，就是我。”最后，父亲的朋友画了一幅画送我，那幅画是一座山峰，山顶有一个人往下看，山下有一个人往上看，两个人是一样大小的。",
