        "passageZh": "一个规模很小的食品公司，生产资金只有十几万。公司生产的辣酱上市之前，老总准备做宣传广告。他本来想在某个热闹的街头租一个显眼的广告牌，让所有人一下子就能注意到他们的产品。但是与广告公司接触后，才发现市中心广告位的价格远远高于他的想象。他并没有失望，而是继续到处打听，最后终于看好一个广告牌。那是一个十字路口，来往车辆很多，但有一点遗憾是，路人行色匆匆，眼睛只顾盯着红绿灯和疾驶的车辆。在这里做广告很难保证有好的效果。询问了一下价格，几万元。老总很满意，于是就租了下来。员工们纷纷提出疑问，但老总只是笑而不答。旧广告很快撤下来，员工们以为第二天就能看到他们的辣酱广告了。然而，第二天，广告牌上根本就没有他们的辣酱，上面只写着：“好位置，当然只等贵客。此广告位招租，88 万/年。”天哪，这样的价格该是这座城市最贵的广告位了吧。天价招牌的冲击力果然不同一般，每个从这里路过的人似乎都不自觉地停住脚步看上一眼。渐渐地，很多人都知道这个十字路口有个贵得离谱的广告位，甚至当地报纸都给予了极大关注„„\n一个月后，“爽口”牌辣酱的广告登了上去。辣酱厂的员工终于明白了老总的心计，无不交口称赞。辣酱的市场迅速打开，因为那“88 万/年”的广告价格早已家喻户晓。“爽口”牌辣酱成为了这座城市的知名品牌。",
