        "partLabel": "Phần 3 • Đọc hiểu bài văn dài chọn đáp án (71–90)",
        "kind": "mcq",
        "passageZh": "每个人心中都有一把快乐的钥匙，但我们却经常把它交给别人掌管。一位女士抱怨道：我活得很不快乐，因为丈夫经常出差不在家。她把快乐的钥匙放在丈夫的手里。一位妈妈说：我的孩子不乖，叫我很生气！她把快乐的钥匙交在孩子的手中。一个男人可能说：老板不欣赏我，所以我情绪不好。他把这把钥匙交给了老板。这些人都做了相同的决定——让别人来控制他的心情。当我们让别人控制我们的情绪时，我们便觉得自己是个受害者，对现状毫无办法，抱怨与愤怒成为唯一的选择。我们开始责怪他人：我这么痛苦都是你造成的，你要为我的痛苦负责。其实，我们是在要求周围的人使自己快乐。我们似乎承认自己无法控制自己，只能可怜地让别人来决定。一个成熟的人能够掌握自己快乐的钥匙，他不必期待别人使他快乐，反而能将快乐与幸福带给别人。他情绪稳定，能为自己负责，和他在一起是种享受，而不是压力。你的钥匙在哪里？在别人手中吗？快去把它拿回来吧。",
