        "audioZh": "“遵医嘱”是什么意思？第21 到25 题是根据下面一段采访： 女：我们今天有幸邀请到了台湾著名的收藏家王度先生，聊一聊老人家的收藏经历。请问您是什么时候开始对文物收藏感兴趣的？ 男：上个世纪六十年代，那时候我在美国留学打工，有一天，在一家店里看到六把小紫砂壶，非常漂亮。老板开价每把一百美元，我当时月薪只有三百美元，于是省吃俭用全部都买下了。后来请人一鉴定，才知道其中一把壶已经流传了四百多年，我的收藏就是这么开始的。后来，我去几个博物馆参观，一看那么多中国文物都在外国人的博物馆里，我就说，我将来有钱啊，一定要做收藏，都给它们买回来。现在我想开了，在他们的博物馆，成千上万的人去参观，看到的也是中国的东西。 女：听说您的收藏品台湾和大陆都有，捐出去的比卖的多。 男：这没有什么不好，只是你要换个角度想。有舍才有得。捐给博物馆，它们可以永久替我保存。凡有学校、博物馆能保护好这些文物，我都捐。 女：您把所有的财产都用来收藏文物，甚至卖房子也要买文物，您觉得值得吗？ 男：我认为我做的，比我父亲留给我房子还要好。当时不知道，现在我认为我做对了。钱再多，就多一个零嘛，一百亿和一千亿根本没有区别。但我保护文物五十年如一日，现在树也长大了，花也开了，开始结果了，是该收获的时候了。 女：您去年获得了北京大学的荣誉博士学位，这对您来说算是一种收获吗？ 男：我一个小商人，能拿到北大的博士学位，不是因为我有钱，是因为我保护中华文物五十年。 女：五十年您收获了一个荣誉博士，您今后还打算收获些什么？ 男：老天对我已经太厚爱了，我得到了我所有想要的东西。但我还有一个梦想，我收藏了一对明朝的刀，已经收藏三十年了。别人出多少钱，我都不会卖。我想等我死了以后一把送给大陆，一把送给台湾，希望将来能存在一起，这两把刀应该留在我们中国。",
