        "audioZh": "男的还有什么愿望？第26 到30 题是根据下面一段采访： 女：早在电视剧《暗算》之前，麦家已经成名，那是2002 年出版的小说《解密》带给他的荣誉。《解密》讲述了一群数学奇才，被选送到秘密单位，身负国家重大使命，破译密码。麦老师，感谢您今天接受我们的访谈，您对于目前作品的宣传怎么看？ 男：我觉得一个作家还是应该躲在文字背后。作家不是政治家，也不是明星，不是通过自己的形象来征服观众，而是通过文字，也就是通过思想和读者打交道。 女：之前想过自己的作品会成为畅销书吗？ 男：肯定不会。《解密》刚出版时，市场很冷淡。但转眼间，这种描写英雄人生的作品受到了市场的热捧，所以说读者是不可设计的。另外，能否成为畅销书是出版商考虑的，作家的乐趣在写的过程中。不要去想读者喜欢什么样的作品，要想什么样的作品是你最适合写的，什么样的东西是你写了别人就写不了的。 女：那么这几年您的作品越来越畅销，对您的创作有什么影响吗？ 男：受干扰越来越多，而我感觉自己的作品越来越差。写作需要专心，而且不是一时的专心，需要长期的专心，需要一种孤独。沉思状态下才能想出别人没想到的，写出别人没写出来的，这样的写作才是有意义的。 女：现在商业上的成功对您来说意味着什么？ 男：每一个作家都希望自己的书有更多的读者，在市场上能够大卖。每一个人都有虚荣心，我想一个作家的虚荣心就体现在这个方面，就是自己的书有更多的读者，被广大的读者喜欢。 女：您的作品《暗算》同时获得了茅盾文学奖，这会让您觉得有成就感吗？ 男：获奖与商业上的成功一样，都是一种鼓励和肯定，对作家来讲，也是一种安慰。但写作肯定不是为了获奖。 女：那么，让您真正感到内心满足的事情是什么？ 男：每一个作家都有内心自我的期待，自己的标准，就像跳高运动员一样，我们内心也始终有一个高度，每一次写作都想越过去。如果有一天真正写出让自己内心满意的作品，写作就会停止下来。我期待某部作品写出来之后，我所有想说的话都在这个作品里说完了，这样自己就会是一个很幸福的作家。",
