        "statementPy": "",
        "audioZh": "关于扁鹊，可以知道什么？第37 到40 题是根据下面一段话：人类文明经历了三个阶段。第一阶段是原始文明。约在石器时代，人们必须依赖集体的力量才能生存，物质生产活动主要靠简单的采集、渔猎，为时上百万年。第二阶段是农业文明。铁器的出现使人改变自然的能力产生了质的飞跃，为时一万年。第三阶段是工业文明。18世纪英国工业革命开启了人类现代化生活，为时300 年。300 年的工业文明以人类征服自然为主要特征。世界工业化的发展使征服自然的文明达到极致，一系列全球性生态危机说明地球再没能力支持工业文明的继续发展。需要开创一个新的文明形态来延续人类的生存，这就是生态文明。如果说农业文明是“黄色文明”，工业文明是“黑色文明”，那生态文明就是“绿色文明”。生态文明是人类文明的一种形态，它以尊重和维护自然为前提。生态文明既追求人与生态的和谐，也追求人与人的和谐，而且人与自然和谐是人与人和谐的前提，它强调尊重和保护环境，强调人类在改造自然的同时必须尊重和爱护自然，而不能随心所欲，盲目蛮干，为所欲为。",
