        "passageZh": "有个孩子，在他出生的那天，妈妈就离开了人世。从此，每当看到别人从妈妈那儿得到礼物，他就非常伤心：“唉，我真命苦，（71）。”一天，这孩子想起这件事，又伤心地哭了。他独自在街上徘徊，泪水模糊了双眼，撞在一位老人身上。老人并不生气，还关切地问：“孩子，你哭什么？”（72）。老人听罢，严肃地说：“孩子，你错了！其实，你妈妈为你留下了最珍贵的礼物，你应该珍惜才对。”“那„„我怎么会不知道？”孩子惊讶地问。老人抚摸着孩子的头，语重心长地说：“首先，你妈妈从你出生那天起，（73）。这难道还不够吗？”老人接着说：“不仅如此，妈妈还给了你明亮的眼睛，让你去观察世界；给了你灵敏的耳朵，让你去倾听世界；给了你一双腿，让你去走遍世界；给了你一双手，让你去改造世界。这些，难道还不够吗？”（74）。老人又说：“孩子，最重要的，妈妈还给了你一颗充满热血的心，（75）！”",
