        "passageZh": "牛奶是最古老的天然饮料之一。它因含有丰富的蛋白质、维生素、钙等营养物质而受到人们的欢迎。最难得的是，牛奶是人体钙的最佳来源，而且钙磷比例非常适当，（76）。但是牛奶也并非某些商家宣传的那样是“完美食品”。全脂牛奶含有大量的饱和脂肪酸和胆固醇，这对心血管健康比较不利。对多数人来说，每天喝一两杯牛奶，是一种很好的饮食习惯。但是对于那些高血脂、高胆固醇的人，（77）。豆浆是来自于大豆的产品，一方面，它和牛奶一样，也含有丰富的蛋白质。另一方面，豆浆中主要是不饱和脂肪酸，不含有胆固醇，（78）。目前越来越多的消费者倾向于认为用豆浆代替牛奶是一种更健康的选择。不过大部分西方人无法接受豆浆强烈的豆味儿，（79），使豆浆在欧美市场上的推广困难重重。总而言之，（80）。牛奶的长处在于补钙，短处是不利于心血管、不利于减肥；而豆浆则正好相反，长处是有利于心血管、有利于减肥，短处是不含钙。",
