        "passageZh": "超级美女，在人生的道路上总是能够得到眷顾，但在通往婚姻的道路上，却往往比那些普通女子艰难许多。一般来说，越是品质好的产品，销路越好。但这并不意味着质量更好的产品，销路就更好。商店橱窗里展示的精品，往往是少人问津的产品。这不是因为它们质量不好，而是因为它们的质量太好。质量太好，因而也就价格太高。如果不打折，能够买得起的人就没有几个。我曾去一个名表城里买手表，其中有一款手表制作精美，让人一看就想买。但一问价格，我就彻底地放弃了这个想法，因为那款手表的标价超过50万元人民币。我买了一块万元出头的手表后，与营业员聊了聊。营业员说万元左右的名表销得最快，而这款50多万元的超级名表，摆了两年也只卖出去一个。如果不是碰巧遇到个把阔绰的买主，这些贵得惊人的表中精品，就只好陈列在橱窗里了。爱情的“市场”上，其实每个人也是“商品”，质量的高低影响着销路的好坏。所以，人人都希望自己是精品，在适当的价格下求得畅销。但一旦变成超级精品，就难逃脱橱窗精品的命运。许多长得平常的女子，往往摘到了幸运的爱情麦穗。而美女，尤其是有学问、有气质又有令人咋舌收入的美女，却往往难以选摘到自己满意的爱情麦穗。按照民间的通俗说法，是越优秀越难嫁。",
