        "partLabel": "Phần 4 • Đọc hiểu văn bản dài chọn đáp án (81–100)",
        "kind": "mcq",
        "passageZh": "在寒冷季节的清晨，草叶上、土块上常常会覆盖着一层霜的结晶。它们在初升的阳光照耀下闪闪发光，待太阳升高后就融化了。人们常常把这种现象叫“下霜”。翻翻日历，每年10 月下旬，总有“霜降”这个节气。我们看到过降雪，也看到过降雨，可是谁也没有看到过降霜。其实，霜不是从天空降下来的，而是在近地面层的空气里形成的。霜是一种白色的冰晶，多形成于夜间。少数情况下，在日落以前太阳斜照的时候也能形成。通常，日出后不久，霜就融化了。但是在天气严寒的时候或者在背阴的地方，霜也能终日不消。霜本身对植物既没有害处，也没有益处。通常人们所说的“霜害”，实际上是在形成霜的同时产生的“冻害”。霜的形成不仅和当时的天气条件有关，而且与所附着的物体的属性也有关。当物体表面的温度很低，而物体表面附近的空气温度却比较高，那么在空气和物体表面之间有一个温度差，较暖的空气和较冷的物体表面相接触时空气就会冷却，形成水汽，当温度降到0°C 以下时，多余的水汽就在物体表面上凝华为冰晶，这就是霜。另外，云对地面物体夜间的冷却是有妨碍的，天空有云不利于霜的形成，因此，霜大都出现在晴朗的夜晚，也就是地面冷却强烈的时候。此外，风对于霜的形成也有影响。有微风的时候，空气缓慢地流过冷物体表面，不断地供应着水汽，有利于霜的形成。但是，风大的时候，由于空气流动得很快，接触冷物体表面的时间太短，上下层的空气容易互相混合，不利于温度降低，从而也会妨碍霜的形成。大致说来，当风速达到3 级或3 级以上时，霜就不容易形成了。因此，霜一般形成在寒冷季节里晴朗、微风或无风的夜晚。",
        "passagePy": "",
        "passageVi": "",
        "q": "关于第4 段中的“温度差”，下列哪项正确？",
