        "sourceZh": "一辆装有满满一车货物的汽车行驶到一座桥下，停了下来。司机下了车，发现自己的车可能过不去。他想，还是先试试吧，可是尝试了几次，都没能通过这座桥，因为汽车装载的货物太满了，已经超过了桥的高度。后来司机量了量，发现汽车的高度仅仅高出了两厘米，但正是这区区两厘米让他在这儿耽误了很长时间。老板一再催促他赶快进站，因为货物需要马上发出去，如果错过了这次发货时间，那老板就可能要赔一大笔钱。眼看着就要到终点站了，他却被卡在这儿，动弹不得。虽然心里十分着急，可是司机仍然想不出一点儿办法。于是他向众人求助，希望周围的人能给他想出一个既省时又省力的办法。一个身强力壮的年轻人走过来对他说：“这还不简单？先把车顶的货物卸下来一些，等过了桥大家再帮你装上去，这不就解决问题了吗？”这个建议很快就被司机否定了，因为那些货物都是由专业的装卸工装上去的，如果卸下来的话，要想再装上去恐怕没那么容易。再说，这样搬来搬去，实在是既浪费时间又需要太多的人力。有个中年人从人群中站了出来，他缓缓说道：“就差两厘米。你可以考虑找几个人爬到车顶上去，然后使劲往下踩几下，这样，车上的货物不就可以低一些了吗？”中年人的话音刚落，货车司机就跳了起来，他连忙向中年人摆手，一边大声说道：“这可使不得，这可使不得。车上装的全都是严禁踩踏的物品，就连装货时，工人都得小心轻放。一路上我也一直小心开车，避免出现颠簸。绝对不可以上去踩，这个办法行不通。”一个年轻女子笑了，“你为什么非要从这儿过去呢？你退回去，从前面那个路口退出去，东边还有一条路，你从那儿走不也一样吗？”司机摇了摇头，说：“那条路我知道，一个是绕远，要多走将近一个小时的路，另外，那条路上也有桥，说不定比这座桥还要矮，到那时„„这个办法行不通。”这也不行，那也不行。众人虽然非常热心地帮助这个货车司机寻找解决问题的办法，可是却一直没能找出一个合适的法子。就在大家一筹莫展的时候，一群刚刚放学的小孩子路过这里，正要过桥。在得知事情的来龙去脉之后，其中一位小男孩向货车司机说：“我有一个办法，把车胎放一点儿气，车的高度就会减少几厘米，你只要把车胎里的气放出来一些不就可以了吗？”人们稍一思考，都忍不住伸出大拇指来夸小男孩的方法好。最后，司机开着车顺顺利利地过了桥，把货物按时送到了终点站。",
        "sourcePy": "",
        "sourceVi": "",
