        "audioZh": "关于男的，可以知道什么？第21 到25 题是根据下面一段采访： 女：今年的大学毕业生就业招聘高峰期即将到来，除了按部就班地参加招聘会外，还有部分大学生选择了自主创业。我们从媒体的报道了解到，大学生创业热情很高，而且政府也提供了很多扶持政策，似乎创业前景不错。周老师，您怎么看呢？ 男：客观地说，大学生的创业前景不错，但现实却不容乐观。从近几年的统计数据来看，创业者中有百分之三十能够达到目标就很不错了。我想对大学生朋友说的是，创业想要成功，重要的是提升自主创业的综合实力，光有决心是不够的。 女：很多大学生朋友有知识、有文化、有热情，但缺乏社会经验和对市场的调研，苦于找不到创业的头绪。您认为怎样才能使他们很好地迈出第一步呢？ 男：首先要根据个人实际情况，制订一个切实可行的创业计划。俗话说“凡事预则立，不预则废”，创业也应当如此。创业计划要包括预期目标、市场前景、管理方式、风险预测等等，应尽量详细，并且在实际实施中不断修订。 女：您认为选取项目时应当考虑的首要因素是什么？ 男：选项目主要根据个人兴趣、行业前景等因素来确定。选项目一定要选自己最熟悉的项目，行业的话要做未来发展前景好、回旋空间大的行业。 女：为了保证创业项目的正常启动，怎样能够筹措资金，也是大学生创业者十分关注的一个问题。您认为怎样才能把握好资金呢？ 男：如果把创业项目比做一个人的躯体，资金则好比赖以生存的血液。创业必须具有创业启动资金。资金的多少视项目需求而定，通常所说的大投入大收获、小投入小收获就是这个道理。资金不足时要用好、用足了政府的创业扶持政策，则相当于降低或减少了创业成本。当然，也可以实行联合创业，也叫加盟创业，就是利用别人的技术、资金进行自主创业。这也是解决启动资金问题的一个办法。",
