        "audioZh": "这项研究关注孩子的什么？第37 到39 题是根据下面一段话：有一天，乘电梯的时候，我和往常一样，仰头看着显示的楼层数，突然意识到我每次乘电梯的时候都会仰着头往上看，这是为什么呢？而且，我看了看周围的人，发现他们竟然和我一样，也都仰着头看着显示的楼层数。难道显示的楼层数有什么神奇的魔力吗？实际上，乘电梯往上看的行为与我们的“私人空间”有着很大的关系。所谓私人空间，是指在我们周围一定的空间，一旦有人闯入我们的私人空间，我们就会感觉不舒服、不自在。私人空间的大小因人而异，但大体上是零点六到一点五米左右的距离。调查数据显示，女性的私人空间比男性的大，具有攻击性格的人的私人空间更大。在电梯中我们会感觉不自在，就是因为有人进入了自己的私人空间，大家都想尽早离开这个狭窄的空间，向上看正是想尽快“逃离”这个狭小空间的心理表现。",
