        "passageZh": "如果给甲一个机会，给乙300 个机会，那么，（71）？如果要你选，我想，你一定会选乙，因为乙拥有比甲多得多的机会，所以乙也就更有可能把握机会了。（72），我们先来读读下面的故事吧。有一位射击运动员，开始时，教练每天给他300\n发子弹进行训练，（73），还没对准靶心就随意地发射，结果射击成绩一直得不到提高。后来，教练改变了训练方法，每天仅给他一发子弹，因为只有一发子弹可以发射，只有一次机会，所以他训练起来变得格外认真，（74）。经过一段时间的训练后，他的射击成绩突飞猛进。“1”为什么大于“300”？就是因为“1”是“唯一”，失去了这“唯一”，就什么也没有了，所以人们对这个“1”就看得格外珍重。而如果换上“300”，失去了其中一个“1”，还有许多个“1”，所以人们对失去其中的一个又一个“1”，也就漠然视之，正因为这种漠然视之的态度，（75）。",
