        "passageZh": "汉朝末年，天下纷争。刘备十分重视人才，他听说诸葛亮的大名后，（76），想请诸葛亮出来帮助他治理国家。恰巧诸葛亮这天不在家，刘备只好失望地回去了。不久，刘备又和关羽、张飞冒着大风雪去请诸葛亮。不料诸葛亮这次又出外闲游去了。张飞本不愿意再来，见诸葛亮不在家，就催着要回去。（77），表达自己对诸葛亮的敬佩之情和请他出来帮忙治理国家的意思。过了一段时间，（78）。刘备又准备去请诸葛亮，关羽说，诸葛亮也许只是徒有一个虚名，未必有真才实学，不用再去了。张飞生性鲁莽，主张由自己一个人去叫就可以了，如果诸葛亮不来，就用绳子把他捆来。刘备把张飞责备了一番，又和他俩第三次去拜访诸葛亮。到了诸葛亮家时，诸葛亮正在睡觉。刘备不敢惊动他，（79），才请他谈话。（80），就跟着刘备出山，全力辅佐刘备治理国家，建立了强大的蜀汉王朝。这就是中国四大名著之一——《三国演义》里讲的“三顾茅庐”的故事。",
