        "partLabel": "Phần 4 • Đọc hiểu văn bản dài chọn đáp án (81–100)",
        "kind": "mcq",
        "passageZh": "有一个年轻人和一个老人同时坐在岸边垂钓。到了傍晚，年轻人的鱼筐里空空如也，老人却收获颇丰，鱼筐里装满了大大小小的“战利品”。年轻人很奇怪，迷惑不解地上前询问老人：“您好，请教您一个问题。您看，咱们几乎是同时来这里钓鱼的，我看您也没用什么特别的诱饵，为什么我钓了一天都毫无收获，您却满载而归呢？”老人微笑着说：“其实道理很简单。你们年轻人大都有一种通病，那就是做什么事情都很浮躁，动不动就心急了。我注意到，你钓鱼的时候总是沉不住气，时不时动动鱼竿，发发牢骚，或者在岸边焦躁地走来走去。本来鱼很可能要上钩了，被你这么一影响，就游走了。而我钓鱼时基本上是一种忘我的境地，静气凝神地守在岸边，让鱼儿在上钩之前根本感觉不到我的存在。钓鱼是一件讲究耐心的事，如果缺乏平和的心态，你就无法让鱼上钩。”有时候，投资失败并非输在外在的客观条件上，甚至在客观条件很好的情况下，有人仍然会“颗粒无收”或者“功亏一篑”，其主要原因就在于我们浮躁的心态，捂不住手里的牌，轻易地就甩了出去，结果往往是追悔莫及。大凡成功的投资者，都是“戒骄戒躁”的高手，他们每逢大事都能保持冷静，善于控制自己的情绪，以稳健又不失迅速的行动追求赢利。",
