        "passageZh": "科普与流行文化之间就真的那么水火不容吗？当然不是。科普作品与严格的科学研究著作之间的主要差别，在于前者的受众主要是科学界之外的公众，而后者则是科学领域中的专家。对于专家，当然不必更多地考虑通俗、普及和喜闻乐见的形式问题，但当面向公众时，这些问题却是不可回避的。当科普作品本身并不流行普及时，我们首先应该从自身找原因，而不只是一味地责备受众缺少什么科学素养和人文品位之类的东西。即使受众真是因为缺少这些东西而使得科普作品难以流行，那也只能说是科普作品的作者工作没有做到位，没有很好地履行其宣传普及的职责而已。流行文化之所以会变得流行，肯定有其道理，有其规律。其实，流行文化也并非只顾流行而不负载任何理念。相对来说，在人文社会科学领域中，情况要稍好一些，至少我们还可以看到像蔡志忠对古典人文作品的漫画演绎，看到对艰深的哲学的图说等。在科普工作以及在范围更广的教育领域中，我们经常听到的一种说法，就是寓教于乐。或许这也正是科普作品不能流行的重要原因之一。在这里，认为只有教以及相关的学习，才是最终的目的，而只将乐作为达到这一目的的一种手段，实际上，这样做恰恰是把目的和手段相混淆了。如果反过来，以一种新的方式来思考和工作，也许效果会大大不同。那些理想而有益的流行文化的特征，恰恰就是乐字当头，教也就在其中。对于科普，也是同样的道理。因此，我们既需要研究流行文化与科普工作的关系，也需要在实践中努力将科普作品做成流行文化的样式，并最终使科普也成为流行文化的一部分。",
