        "passageZh": "著名画家张大千留着飘逸的白胡子，看上去颇有仙风道骨的气质。一个朋友见到大师，好奇地问道：“张先生，您睡觉时，胡子是放在被子上面，还是搁在里头？”张大千每天上床睡觉，从来没注意过自己的胡子，故而据实道来：“这„„我也不清楚。是啊，我怎么没在意这个呢？这样吧，明天再告诉你。”这天晚上，张大千躺在床上，将胡子放在被子上面，觉得好像有点儿不太对劲，把它捋到被子里头，也感觉不像是那么回事。真可谓“里也不是，外也不是”，怎么折腾都觉得不妥。他不由得感叹：“以前这根本就不算是什么事，现在怎么成了头痛的问题呢？”心理学家做过一项实验，人们穿针的时候，神情越是专注，越是不容易穿进去。他们称这种现象为“目的颤抖”，也就是人们通常所说的“穿针心理”。有时，事情就是这样，你目的性越强，越容易把事情搞糟。你越是特别在意什么，它给你带来的困扰就越大。打个比方说，噪声达到同样的分贝，有的人感觉要强烈一些，有的人感觉就没那么明显。只缘前者更在意噪声，所受的影响和危害也就更大。即使是同一个人，听到同样分贝的噪声，当他心不在焉的时候，就不会觉得噪声有多么严重；当他被噪声牵制了注意力，搞得心神不宁的时候，就会感到噪声大得难以容忍。有时，受伤带来的疼痛，也和人的注意力有关。一个人精力高度集中时意外受伤，往往感觉不到疼痛，也不知道自己受伤。一旦看到伤口在流血，他就会慢慢恢复痛感。很多人都有过这样的体验，其实受伤时疼痛已经造成，只是人全神贯注于别的地方，感觉都倾注到了别的因素上，所以掩盖了本身的痛觉。",
