        "partLabel": "Phần 4 • Đọc hiểu văn bản dài chọn đáp án (81–100)",
        "kind": "mcq",
        "passageZh": "一个人要有所创新，必须具备三项基本素质，即识、胆、才。识，指的是眼力，对事物的洞察力与敏感度；胆，指的是魄力，面对未知世界敢于探险的精神；才，指的是智力，包括文化水平、技艺方法等。三者相互依存，缺一不可。这三方面素质的形成，很大程度上取决于一个人所拥有的信息量，而信息量的多少，与其工作环境、居住条件、流动性有很大关系。一个人如果长期在一个相对不变的环境中循环往复地生活，没有新信息激发他去思考、去比较，就很容易思维僵化，更难有预测未来的能力。相反，一个人若生活在无限广阔的天地里，处于不断变化的环境中，时刻接触一些新的信息，“摩擦生热”的法则就会发生作用。他可以思路大开，把自己在不同环境中观察到的事物加以比较，找出规律，并以此预测未来，发现社会的“大趋势”。一个人长期依偎在父母身边，每说一句话都要看看周围人的眼色，特别是父母对自己的态度，这会导致他遇事谨小慎微，工作循规蹈矩。相反，如果置身于大千世界，他就敢想敢说，敢于向传统观念挑战，敢于冒险，敢于创新。一个人走向四方，要适应新环境，这会激发他的求知欲，学习、学习、再学习就会成为他的一种习惯。与知识丰富的人一起工作，可以培养他的竞争力、进取心、好胜心，促使他孜孜不倦地去追求，以获得胜过别人的能力。广泛的社会交往更会使他思路开阔，乐于接受新的东西。在现代社会，衡量人才的标准不仅是知识储备，更重要的是创新能力。如果一个人不能把他所掌握的知识当做创新的源泉，他对社会的贡献将会十分有限。",
