        "sourceZh": "门口草坪上的露珠泛着清晨的阳光。“再见，晚上见。”我冲着妻子挥挥手，然后回到餐厅看孩子是不是吃完了早饭，接下来，准备送他去学校。工作曾经是我生命中最重要的部分。我和朋友合伙开了一家小型科技公司，经济危机来了，公司没了生意，我也失业了。接着我到处搜集招聘信息，不断投简历，但是毫无音信。时间一点一点地“蚕食”着家里的积蓄，我却一筹莫展。一天晚上，妻子和我坐在客厅里发愁。我说：“我们的经济出现了问题，而且问题很严重。”妻子说道：“没关系，下个月我可以回学校去教书。”这句体贴的话，对我来说更像个打击。我们俩都觉得其中一个人待在家里照顾孩子比较好，但我从没想过那个人会是我。妻子顺利地上班了，我却一下子失去了原来的生活节奏，每天奔波于家、学校和超市之间，送孩子上学，放学接他回家，穿着围裙洗衣做饭。开始的几个星期，孩子几乎每天都要吃做糊了的饭菜，穿没有洗干净的衣服，我很奇怪为什么放了那么多洗衣液还是洗不干净，甚至还有好几件衣服被我熨出了洞。我感到非常沮丧，这种生活对于一个曾经视事业如生命的男人来说简直是种折磨，而我的电子邮箱里还是一封邮件也没有。妻子吃着做糊了的米饭，笑着说：“还不错。老公，你会越来越棒的。”一天下午，我接孩子放学，看时间还早，就带他来到附近的一个公园，看到另一个家长在和孩子玩耍，居然也是个男人。他主动上前和我攀谈起来：“我每天都来接女儿放学，然后和她一起来这儿玩。”男人继续说道：“经济危机来了，公司给我放了长假，我主动提出在家照看孩子，你呢，在忙什么？”他还是问了我最不想听到的问题。“没什么，我，我也是待在家里照顾孩子。”我感到非常尴尬。“你真是太幸运了，和我一样幸运，不是吗？我的父亲是个工作狂。我小时候他总是没时间陪我，我多么希望他能带我去游泳、去溜冰„„那时我就告诉自己，将来当了父亲绝不能像他一样。但事实上，等我当了父亲，我却经常到各地出差，不是在飞机上就是在开会，我和女儿的交流只能在电话里进行。所以现在我不能再浪费这个机会了。这是老天对我的恩赐。”幸运？恩赐？他居然这样想。那个男人走后，我看着来回追逐的孩子们，忽然感觉轻松了很多。女儿最喜欢哪双鞋？儿子最喜欢吃什么蔬菜？有多少爸爸能脱口而出呢？现在我从孩子身上学到的东西是工作时无论如何也学不到的。更重要的是，我现在能和孩子每天面对面地交流，这在以前是做不到的，而这种交流会影响他的一生。现在我明白了，在我面前的确是一个千载难逢的机会，能和孩子们一起成长不就是我现在的工作吗？我的工作应该远比挣100 万更有意义。",
